// Additional open-position ukulele shapes for the complete learning arrangements.
// Pitch content is verified against g4 C4 E4 A4 in tests; repeated finger numbers indicate a barre.
const extraShapes={
 A:{frets:[2,1,0,0],fingers:[2,1,0,0],label:'A major',tip:'Middle finger on g2, index on C1. E and A stay open.'},
 Am7:{frets:[0,0,0,0],fingers:[0,0,0,0],label:'A minor seventh',tip:'All four strings open. Keep the fretting hand relaxed.'},
 Bb:{frets:[3,2,1,1],fingers:[3,2,1,1],label:'B-flat major',tip:'Barre E and A at fret 1 with your index. Middle on C2, ring on g3.'},
 Bm:{frets:[4,2,2,2],fingers:[3,1,1,1],label:'B minor',tip:'Barre C, E and A at fret 2 with your index. Ring on g4.'},
 D:{frets:[2,2,2,0],fingers:[1,2,3,0],label:'D major',tip:'Index on g2, middle on C2, ring on E2. Let A ring open.'},
 D7:{frets:[2,2,2,3],fingers:[1,1,1,2],label:'D dominant seventh',tip:'Barre g, C and E at fret 2. Middle finger on A3.'},
 Dm:{frets:[2,2,1,0],fingers:[2,3,1,0],label:'D minor',tip:'Middle on g2, ring on C2, index on E1. A stays open.'},
 Dm7:{frets:[2,2,1,3],fingers:[2,3,1,4],label:'D minor seventh',tip:'Form Dm, then add your little finger on A3.'},
 E:{frets:[1,4,0,2],fingers:[1,4,0,2],label:'E major',tip:'Index on g1, little finger on C4, middle on A2. E stays open. Take the stretch slowly.'},
 E7:{frets:[1,2,0,2],fingers:[1,2,0,3],label:'E dominant seventh',tip:'Index on g1, middle on C2, ring on A2. E stays open.'},
 Eb:{frets:[0,3,3,1],fingers:[0,2,3,1],label:'E-flat major',tip:'Middle on C3, ring on E3, index on A1. Let g ring open.'},
 Em:{frets:[0,4,3,2],fingers:[0,3,2,1],label:'E minor',tip:'Index on A2, middle on E3, ring on C4. Let g ring open.'},
 G7:{frets:[0,2,1,2],fingers:[0,2,1,3],label:'G dominant seventh',tip:'Middle on C2, index on E1, ring on A2. Let g ring open.'},
 Gm:{frets:[0,2,3,1],fingers:[0,2,3,1],label:'G minor',tip:'Middle on C2, ring on E3, index on A1. Let g ring open.'}
};
const pitchNames=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B'];
for(const [name,shape] of Object.entries(extraShapes)){
 const notes=shape.frets.map((f,i)=>{const midi=[67,60,64,69][i]+f;return pitchNames[midi%12]+(Math.floor(midi/12)-1);});
 CHORDS[name]={...shape,notes,color:'mint',check:'Pick each string separately. Keep fretting fingers curved and close to the fret wires.',transition:'Practice the change slowly before playing it in a whole song.'};
}
